INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_NOR_AEGIR_POETIC','ENT_NOR_AEGIR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Aegir, who was well skilled in magic, once went to Asgard, where he met with a very good reception. Supper time being come, the twelve mighty Aesir,--Odin, Thor, Njord, Frey, Tyr, Heimdall, Bragi, Vidar, Vali, Ullur, Hoenir and Forseti, together with the Asynjor,--Frigga, Freyja, Gefjon, Iduna, Gerda, Siguna, Fulla and Nanna, seated themselves on their lofty doom seats, in a hall around which were ranged swords of such surpassing brilliancy that no other l','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_AESIR_POETIC','ENT_NOR_AESIR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','His wife is Frigga, the daughter of Fjorgyn, and they and their offspring form the race that we call Aesir, a race that dwells in Asgard the old, and the regions around it, and that we know to be entirely divine. Wherefore Odin may justly be called All-father, for he is verily the father of all, of gods as well as of men, and to his power all things owe their existence.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_ANDVARI_POETIC','ENT_NOR_ANDVARI','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','He informed Sigurd of his parentage, and how it befell that Odin, and Hoenir, and Loki came to Andvarafors (the waterfall of Andvari). In the fall there was an abundance of fish. There was a dwarf named Andvari, who had long lived in the fall in the likeness of a pike, and in which he supplied himself with food. "Our brother," continued Regin, "was named Otr, who often went into the fall in the likeness of an otter.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_BALDR_POETIC','ENT_NOR_BALDR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Together were the Aesir all in council, and the Asyniur all in conference, and they consulted, the mighty gods, why Baldr had oppressive dreams. 2. [To that god his slumber was most afflicting; his auspicious dreams seemed departed. They the Jotuns questioned, wise seers of the future, whether this might not forebode calamity? 3.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_BESTLA_POETIC','ENT_NOR_BESTLA','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Potent songs nine from the famed son I learned of Bolthorn, Bestla''s sire, and a draught obtained of the precious mead, drawn from Odhraerir. 143. Then I began to bear fruit, and to know many things, to grow and well thrive: word by word I sought out words, fact by fact I sought out facts. 144.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_DVALINN_POETIC','ENT_NOR_DVALINN','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Sol among men ''tis called, but with the gods sunna, the dwarfs call it Dvalinn''s leika, the Jotuns eyglo, the Alfar fagrahvel, the Aesir''s sons alskir. _Vingthor_. 18. Tell me, Alvis, etc., how the clouds are called, which with showers are mingled in every world. _Alvis_. 19. Sky they are called by men, but skurvan by the gods; the Vanir call them vindflot, the Jotuns urvan, the Alfar vedrmegin; in Hel they are called hialm hulids. _Vingthor_. 20.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_EINHERJAR_POETIC','ENT_NOR_EINHERJAR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','As it is said:-- "''The Einherjar all On Odin''s plain Hew daily each other, While chosen the slain are. From the fray they then ride, And drink ale with the Aesir.'' "Thou hast thus reason to say that Odin is great and mighty, for there are many proofs of this.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_FENRIR_POETIC','ENT_NOR_FENRIR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Be silent, Ty! Thou couldst never settle a strife ''twixt two; of thy right hand also I must mention make, which Fenrir from thee tore. _Ty_. 39. I of a hand am wanting, but thou of honest fame; sad is the lack of either. Nor is the wolf at ease: he in bonds must bide, until the gods'' destruction. _Loki_. 40. Be silent, Ty; to thy wife it happened to have a son by me. Nor rag nor penny ever hadst thou, poor wretch! for this injury. _Frey_. 41.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_FREKI_POETIC','ENT_NOR_FREKI','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Odin,'' replied Har, ''gives the meat that is set before him to two wolves, called Geri and Freki, for he himself stands in no need of food. Wine is for him both meat and drink. "Two ravens sit on Odin''s shoulders and whisper in his ear the tidings and events they have heard and witnessed. They are called Hugin and Munin. He sends them out at dawn of day to fly over the whole world, and they return at eve towards meal time.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_FREYJA_POETIC','ENT_NOR_FREYJA','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','"Njord had afterwards, at his residence at Noatun, two children, a son named Frey, and a daughter called Freyja, both of them beauteous and mighty. Frey is one of the most celebrated of the gods. He presides over rain and sunshine, and all the fruits of the earth, and should be invoked in order to obtain good harvests, and also for peace. He, moreover, dispenses wealth among men.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_FRIGG_POETIC','ENT_NOR_FRIGG','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','She is entrusted with the toilette and slippers of Frigga, and admitted into the most important secrets of that goddess. Freyja is ranked next to Frigga: she is wedded to a person called Odur, and their daughter, named Hnossa, is so very handsome that whatever is beautiful and precious is called by her name (_hnosir_.) But Odur left his wife in order to travel into very remote countries.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_GULLVEIG_POETIC','ENT_NOR_GULLVEIG','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','She that war remembers, the first on earth, when Gullveig they with lances pierced, and in the high one''s hall her burnt, thrice burnt, thrice brought her forth, oft not seldom; yet she still lives. 26. Heidi they called her, whithersoe''r she came, the well-foreseeing Vala: wolves she tamed, magic arts she knew, magic arts practised; ever was she the joy of evil people. 27.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_GUNNLOD_POETIC','ENT_NOR_GUNNLOD','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Suttung having agreed to these conditions, released the dwarfs, and carrying the mead home with him, committed it to the care of his daughter Gunnlauth. Hence poetry is indifferently called Kvasir''s blood, Suttung''s mead, the dwarf''s ransom, etc. ODIN BEGUILES THE DAUGHTER OF BAUGI 72.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_HYMIR_POETIC','ENT_NOR_HYMIR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','It is said that when the giant Hymir beheld the serpent, he turned pale and trembled with fright and seeing, moreover, that the water was entering his boat on all sides, he took out his knife, just as Thor raised his mallet aloft, and cut the line, on which the serpent sunk again under the water.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_LODURR_POETIC','ENT_NOR_LODURR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Spirit gave Odin, sense gave Hoenir, blood gave Lodur, and goodly colour. 19. I know an ash standing Yggdrasil hight, a lofty tree, laved with limpid water: thence come the dews into the dales that fall; ever stands it green over Urd''s fountain. 20. Thence come maidens, much knowing, three from the hall, which under that tree stands; Urd hight the one, the second Verdandi,--on a tablet they graved--Skuld the third.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_MIMIR_POETIC','ENT_NOR_MIMIR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Odin then rides to Mimir''s well and consults Mimir how he and his warriors ought to enter into action. The ash Yggdrasill begins to shake, nor is there anything in heaven or earth exempt from fear at that terrible hour. The Aesir and all the heroes of Valhalla arm themselves and speed forth to the field, led on by Odin, with his golden helm and resplendent cuirass, and his spear called Gungnir.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_MOTSOGNIR_POETIC','ENT_NOR_MOTSOGNIR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Then was Motsognir created greatest of all the dwarfs, and Durin second; there in man''s likeness they created many dwarfs from earth, as Durin said. 11. Nyi and Nidi, Nordri and Sudri, Austri and Vestri, Althiof, Dvalin Nar and Nain, Niping, Dain, Bivor, Bavor, Bombur, Nori, An and Anar, Ai, Miodvitnir, 12. Veig and Gandalf, Vindalf, Thrain, Thekk and Thorin, Thror, Vitr, and Litr, Nur and Nyrad, Regin and Radsvid. Now of the dwarfs I have rightly told.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_MUNDILFARI_POETIC','ENT_NOR_MUNDILFARI','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','"There was formerly a man," replied Har, "named Mundilfari, who had two children so lovely and graceful that he called the male, Mani (moon), and the female, Sol (sun), who espoused the man named Glenur.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_NIDHOGG_POETIC','ENT_NOR_NIDHOGG','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Ratatosk is the squirrel named, which, has to run in Yggdrasil''s ash; he from above the eagle''s words must carry, and beneath to Nidhogg repeat. 33. Harts there are also four, which from its summits, arch-necked, gnaw. Dain and Dvalin, Duneyr and Durathror. 34.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_NJORD_POETIC','ENT_NOR_NJORD','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Yet Njord is not of the lineage of the Aesir, for he was born and bred in Vanaheim. But the Vanir gave him as hostage to the Aesir, receiving from them in his stead Hoenir. By this means was peace re-established between the Aesir and Vanir. Njord took to wife Skadi, the daughter of the giant Thjassi.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_NORNS_POETIC','ENT_NOR_NORNS','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','These maidens fix the lifetime of all men, and are called Norns. But there are, indeed, many other Norns, for, when a man is born, there is a Norn to determine his fate. Some are known to be of heavenly origin, but others belong to the races of the elves and dwarfs; as it is said-- "''Methinks the Norns were born far asunder, for they are not of the same race.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_VANAHEIM_POETIC','ENT_NORR_VANAHEIM','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','In Vanaheim wise powers him created, and to the gods a hostage gave. At the world''s dissolution, he will return to the wise Vanir. _Gagnrad_. 40. Tell me eleventhly, since all the condition of the gods thou knowest, Vafthrudnir! what the Einheriar do in Haerfather''s halls, until the powers perish? _Vafthrudnir_. 41.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_SKIRNIR_POETIC','ENT_NOR_SKIRNIR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','BINDING THE WOLF FENIR "After this, the gods despaired of ever being able to bind the wolf; wherefore All-father sent Skirnir, the messenger of Frey, into the country of the Dark Elves (Svartalfaheim) to engage certain dwarfs to make the fetter called Gleipnir. It was fashioned out of six things; to wit, the noise made by the footfall of a cat; the beards of women; the roots of stones; the sinews of bears; the breath of fish; and the spittle of birds.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_SKULD_POETIC','ENT_NOR_SKULD','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Near the fountain, which is under the ash, stands a very beauteous dwelling, out of which go three maidens, named Urd, Verdandi, and Skuld. These maidens fix the lifetime of all men, and are called Norns. But there are, indeed, many other Norns, for, when a man is born, there is a Norn to determine his fate.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_SLEIPNIR_POETIC','ENT_NOR_SLEIPNIR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','This is the horse Sleipnir, which excels all horses ever possessed by gods or men." OF THE SHIP SKIDBLADNIR. 44. "What hast thou to say," demanded Gangler, "of Skidbladnir, which thou toldst me was the best of ships? Is there no other ship as good or as large?" "Skidbladnir," replied Har, "is without doubt the best and most artfully constructed of any, but the ship Nagffar is of larger size.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_THRYM_POETIC','ENT_NOR_THRYM','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','He first slew Thrym, the Thursar''s lord, and the Jotun''s race all crushed; 33. He slew the Jotun''s aged sister, her who a bride-gift had demanded; she a blow got instead of skillings, a hammer''s stroke for many rings. So got Odin''s son his hammer back. THE LAY OF THE DWARF ALVIS. _Alvis_. 1. The benches they are decking, now shall the bride with me bend her way home.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_VAFTHRUDNIR_POETIC','ENT_NOR_VAFTHRUDNIR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Odin visits the Giant (Jotun) Vafthrudnir, for the purpose of proving his knowledge. They propose questions relative to the Cosmogony of the Northern creed, on the conditions that the baffled party forfeit his head. The Jotun incurs the penalty. _Odin_. 1. Counsel thou me now, Frigg! as I long to go Vafthrudnir to visit; great desire, I say, I have, in ancient lore with that all-wise Jotun to contend. _Frigg_. 2.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_VANIR_POETIC','ENT_NOR_VANIR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','The Vanir, foreseeing conflict, tramp o''er the plains. Odin cast [his spear], and mid the people hurled it: that was the first warfare in the world. 29. Then went the powers all to their judgment-seats, the all-holy gods, and thereon held council: who had all the air with evil mingled? or to the Jotun race Od''s maid had given? 30. There alone was Thor with anger swollen. He seldom sits, when of the like he hears.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_VERDANDI_POETIC','ENT_NOR_VERDANDI','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Near the fountain, which is under the ash, stands a very beauteous dwelling, out of which go three maidens, named Urd, Verdandi, and Skuld. These maidens fix the lifetime of all men, and are called Norns. But there are, indeed, many other Norns, for, when a man is born, there is a Norn to determine his fate.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_YGGDRASIL_POETIC','ENT_NOR_YGGDRASIL','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','I know an ash standing Yggdrasil hight, a lofty tree, laved with limpid water: thence come the dews into the dales that fall; ever stands it green over Urd''s fountain. 20. Thence come maidens, much knowing, three from the hall, which under that tree stands; Urd hight the one, the second Verdandi,--on a tablet they graved--Skuld the third. Laws they established, life allotted to the sons of men; destinies pronounced. 21.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation (Benjamin Thorpe, in the Norroena ed. Gutenberg #14726) located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_DAGR_POETIC','ENT_NOR_DAGR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','She then espoused Delling, of the Aesir race, and their son was Day, (Dagr) a child light and beauteous like his father. Then took All-father, Night, and Day, her son, and gave them two horses and two cars, and set them up in the heavens that they might drive successively one after the other, each in twelve hours'' time, round the world.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_GERI_POETIC','ENT_NOR_GERI','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Geri and Freki the war-wont sates, the triumphant sire of hosts; but on wine only the famed in arms, Odin, ever lives. 20. Hugin and Munin fly each day over the spacious earth. I fear for Hugin, that he come not back, yet more anxious am I for Munin. 21. Thund roars; joyful in Thiodvitnir''s water lives the fish; the rapid river seems too great for the battle-steed to ford. 22.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_LOKI_POETIC','ENT_NOR_LOKI','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Having also seized Loki''s children, Vali and Nari, they changed the former into a wolf, and in this likeness he tore his brother to pieces and devoured him. The gods then made cords of his intestines, with which they bound Loki on the points of the rocks, one cord passing under his shoulders, another under his loins, and a third under his hams, and afterwards transformed these cords into thongs of iron.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_URDARBRUNNR_POETIC','ENT_NORR_URDARBRUNNR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','The Deluding of Gylfi 256 Of the Primordial State of the Universe 259 Origin of the Frost-Giants 260 Of the Cow Audhumla, and Birth of Odin 262 The Making of Heaven and Earth 263 Creation of Man and Woman 265 Night and Day, Sun and Moon 266 Wolves that Pursue the Sun and Moon 267 The Way that Leads to Heaven 268 The Golden Age 269 Origin of the Dwarfs, and Norns of Destiny 270 The Ash Yggdrasill and Mimer''s Well 271 The Norns','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_THOR_POETIC','ENT_NOR_THOR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','My sire, fierce of mood, a kettle owns, a capacious cauldron, a rast in depth." _Thor_. 6. "Knowest thou whether we can get the liquor-boiler?" _Ty_. "Yes, friend! if we stratagem'' employ." Rapidly they drove forward that day from Asgard, till to the giant''s home they came. 7. Thor stalled his goats, splendid of horn, then turned him to the hall that Hymir owned.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
